160	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
161	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
162	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
163	            boolean householdInUse = this.clinicService.findAllOwners().stream()
164	                .anyMatch(existing ->
165	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
166	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
167	            if (householdInUse) {
168	                return new ResponseEntity<>(HttpStatus.CONFLICT);
169	            }
170	        }
171	        // Determine the effective registration date — the value supplied on the request, or the
172	        // server's current date when none was supplied — and roll it forward to the next business
173	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
174	        // registration date (membership-number year segment, per-day create-limit) uses this
175	        // adjusted date.
176	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
177	        if (registrationDate == null) {
178	            registrationDate = LocalDate.now();
179	        }
180	        registrationDate = toBusinessDay(registrationDate);
181	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
182	        // owners have already been registered on this (adjusted) business day.
183	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
184	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
185	        }
186	        ownerFieldsDto.setTelephone(normalizedTelephone);
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        owner.setRegistrationDate(registrationDate);
190	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
191	        // letters of the city, the upper-cased first three letters of the last name, and a
192	        // per-city 4-digit sequence one greater than the number of owners already in that city.
193	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
194	        // Record how many existing owners already share this owner's first and last name
195	        // (compared case-insensitively) at the moment before this owner is created.
196	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
197	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
198	        // registered on this (adjusted) business day before this owner is created.
199	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
200	        // Record the size of this owner's household after this create: the number of existing
201	        // owners sharing the same household (matching last name and address) plus this owner.
202	        // Drives the 'GOLD' membership tier (3 or more members).
203	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
204	        this.clinicService.saveOwner(owner);
205	        // Emit an audit line recording the new owner's id, customer code and registration date.
206	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
207	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
208	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
209	        headers.setLocation(UriComponentsBuilder.newInstance()
210	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
211	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
212	    }
213	
214	    /**
215	     * Validate and normalize the optional owner email in place.
216	     *
217	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
218	     * When present it must be a syntactically valid address; a valid address is
219	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
220	     * present but syntactically invalid, so the caller can reject with 400.
221	     */
222	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
223	        String email = ownerFieldsDto.getEmail();
224	        if (email == null || email.isBlank()) {
225	            ownerFieldsDto.setEmail(null);
226	            return true;
227	        }
228	        String normalized = email.trim().toLowerCase(Locale.ROOT);
229	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
230	            return false;
231	        }
232	        ownerFieldsDto.setEmail(normalized);
233	        return true;
234	    }
235	
236	    /**
237	     * Normalize an owner address: trim, collapse each run of whitespace to a single
238	     * space, upper-case, and expand common street-type abbreviations
239	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
240	     * A {@code null} value normalizes to the empty string.
241	     */
242	    private static String normalizeAddress(String value) {
243	        if (value == null) {
244	            return "";
245	        }
246	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
247	        if (collapsed.isEmpty()) {
248	            return "";
249	        }
250	        String[] tokens = collapsed.split(" ");
251	        StringBuilder sb = new StringBuilder(collapsed.length());
252	        for (int i = 0; i < tokens.length; i++) {
253	            if (i > 0) {
254	                sb.append(' ');
255	            }
256	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
257	        }
258	        return sb.toString();
259	    }
260	
261	    /**
262	     * Normalize an owner household field (last name or address) for duplicate detection:
263	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
264	     * A {@code null} value normalizes to the empty string.
265	     */
266	    private static String normalizeHouseholdKey(String value) {
267	        if (value == null) {
268	            return "";
269	        }
270	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
271	    }
272	
273	    /**
274	     * Normalize a telephone number to E.164 form.
275	     *
276	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
277	     * explicit leading {@code '+'} and country code it is kept; otherwise the
278	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
279	     * dropped from the national digits. The result must contain 8 to 15 digits
280	     * after the {@code '+'}.
281	     *
282	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
283	     *         the input is absent or cannot form a valid E.164 number.
284	     */
285	    private static String toE164(String raw) {
286	        if (raw == null) {
287	            return null;
288	        }
289	        String trimmed = raw.trim();
290	        boolean hasCountryCode = trimmed.startsWith("+");
291	        // Strip spaces, dashes and brackets.
292	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
293	        String digits;
294	        if (hasCountryCode) {
295	            // Keep the explicit country code; drop the leading '+' for validation.
296	            digits = stripped.substring(1);
297	        } else {
